function evidence = f90_xbatt10_extract_candidate_evidence( ...
        modelPath, outputDir)
%F90_XBATT10_EXTRACT_CANDIDATE_EVIDENCE Replay the public EV-truck contract.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot] = localRoots("F90-XBATT-10");
addpath(sharedRoot, "-begin");
cleanup = onCleanup(@() rmpath(sharedRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.f90-xbatt10-evidence.v1", ...
    "task_id", "F90-XBATT-10", ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localRequested, ...
    "stop_time", @(~,~) 12.0, ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "evidence_sample_s", 0.1);
evidence = simuverity_run_candidate_evidence( ...
    modelPath, outputDir, spec);
end

function rows = localOutputs
rows = localRows(["vehicle", "motor", "battery", "controls"], ...
    [4 3 4 4]);
end

function inputs = localInputs(scenario, ~)
[profileTime, profileSpeed] = localProfile(string(scenario.profile));
inputs = struct("ev_truck_input", struct( ...
    "drive_cycle_time_s", profileTime, ...
    "drive_cycle_speed_mps", profileSpeed, ...
    "vehicle_mass_kg", double(scenario.vehicle_mass_kg), ...
    "powertrain_rating_kw", double(scenario.powertrain_rating_kw), ...
    "battery_initial_soc_fraction", ...
        double(scenario.battery_initial_soc_fraction), ...
    "regenerative_braking_enabled", ...
        double(scenario.regenerative_braking_enabled)));
end

function requested = localRequested(scenario, ~)
[profileTime, profileSpeed] = localProfile(string(scenario.profile));
requested = struct( ...
    "profile", string(scenario.profile), ...
    "drive_cycle_time_s", profileTime, ...
    "drive_cycle_speed_mps", profileSpeed, ...
    "vehicle_mass_kg", double(scenario.vehicle_mass_kg), ...
    "powertrain_rating_kw", double(scenario.powertrain_rating_kw), ...
    "battery_initial_soc_fraction", ...
        double(scenario.battery_initial_soc_fraction), ...
    "regenerative_braking_enabled", ...
        double(scenario.regenerative_braking_enabled));
end

function row = localPostprocess(row, outputs, ~, ~)
t = double(outputs.time_s(:));
row.logs = struct( ...
    "vehicle", localLog(t, outputs.vehicle, ...
        {"drive_cycle_speed_kph", "vehicle_speed_kph", ...
         "vehicle_acceleration_mps2", "vehicle_distance_km"}, ...
        {"km/h", "km/h", "m/s^2", "km"}), ...
    "motor", localLog(t, outputs.motor, ...
        {"torque_Nm", "speed_rpm", "mechanical_power_kW"}, ...
        {"N*m", "rpm", "kW"}), ...
    "battery", localLog(t, outputs.battery, ...
        {"voltage_V", "current_A", "power_kW", "soc_fraction"}, ...
        {"V", "A", "kW", "1"}), ...
    "controls", localLog(t, outputs.controls, ...
        {"torque_command_Nm", "brake_command", ...
         "throttle_percent", "brake_percent"}, ...
        {"N*m", "1", "%", "%"}));
row.outputs = outputs;
row.valid = row.output_contract.all_required_pass && ...
    numel(t) == 121 && t(1) <= 1e-9 && abs(t(end) - 12) <= 1e-6;
end

function [time, speed] = localProfile(profile)
if profile == "standard"
    time = [0; 1; 2; 4; 6; 8; 10; 12];
    speed = [0; 0; 4; 10; 10; 6; 0; 0];
elseif profile == "aggressive"
    time = [0; 1; 2; 3.5; 5.5; 7.5; 9.5; 12];
    speed = [0; 0; 7; 16; 16; 8; 0; 0];
else
    error("SimuVerity:F90:XBATT10:Profile", ...
        "Unknown fixed official drive-cycle profile: %s", profile);
end
end

function log = localLog(time, data, channels, units)
log = struct("time", time, "data", double(data), ...
    "channels", {channels}, "units", {units});
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
semantic = structure.semantic_types;
battery = nnz(contains(semantic, "battery"));
motor = nnz(contains(semantic, ["motor", "machine"]));
vehicle = nnz(contains(semantic, ["vehicle", "tire", "wheel"]));
controller = nnz(contains(semantic, ["controller", "pid", "stateflow"]));
audit = struct( ...
    "battery_path_present", battery >= 1, ...
    "motor_path_present", motor >= 1, ...
    "vehicle_dynamics_present", vehicle >= 1, ...
    "closed_loop_control_present", ...
        controller >= 1 && structure.signal_cycle_present, ...
    "connected_public_output_count", structure.connected_output_count, ...
    "core_path_qualified", battery >= 1 && motor >= 1 && ...
        vehicle >= 1 && structure.connected_output_count == ...
        numel(spec.output_contract) && structure.dynamic_block_count >= 1);
end

function rows = localRows(names, widths)
rows = repmat(struct("name", "", "evidence_name", "", ...
    "width", 0, "interpolation", "linear"), numel(names), 1);
for k = 1:numel(names)
    rows(k).name = names(k);
    rows(k).evidence_name = names(k);
    rows(k).width = widths(k);
end
end

function [taskRoot, sharedRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for k = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
end
